const emptyHits = () => ({ items: [], definitions: [], domains: [], people: [] })

const notAvailable = (method: string) => () =>
  Promise.reject(new ApiError('not-available', `The service doesn't offer this yet (${method}).`))

/** The service refused a change for its token: a newer session has a new one. */
const csrfRefused = (error: unknown) =>
  toApiError(error).kind === 'forbidden' && toApiError(error).message === refusals.csrf

/** A card's decision in the service's words, by the outcome the Inbox names it with. */
const cardActions: Record<string, CardAction> = {
  Checked: 'still_true',
  'Not a problem': 'not_a_problem',
  Closed: 'not_written',
  'Not something we write down': 'not_written',
  Archived: 'archive',
}

const isUuid = (id: string) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)
const isItemId = (id: string) => /^itm_[a-z0-9]{8,16}$/.test(id)

/** A change to many items in the service's words, by the bar's action. */
const bulkActions = {
  archive: 'archive',
  delete: 'delete',
  domain: 'domain',
  kind: 'kind',
  'owner-add': 'owner_add',
  'owner-set': 'owner_set',
  check: 'check',
} as const satisfies Record<FactAction, string>

/** A read that finds nothing answers null. */
async function orNull<T>(call: () => Promise<T>): Promise<T | null> {
  try {
    return await call()
  } catch (error) {
    if (toApiError(error).kind === 'not-found') return null
    throw error
  }
}

const randomKey = () => globalThis.crypto.randomUUID()

/** Today on this browser's calendar, as the days an answer names run to. */
const localDay = (at: Date) =>
  `${at.getFullYear()}-${String(at.getMonth() + 1).padStart(2, '0')}-${String(at.getDate()).padStart(2, '0')}`

/** A topic as the pages name it: "Orders in Norway"; with no metric, "Norway, no metric named". */
const topicNameOf = (
  t: { metric: string; where: string; named?: string },
  markets: readonly string[],
) =>
  t.named === 'none' || !t.metric
    ? `${t.where}, no metric named`
    : markets.includes(t.where)
      ? `${t.metric} in ${t.where}`
      : `${t.metric}, ${t.where === 'All markets' ? 'all markets' : t.where}`

/** Two names for the same word: case aside. */
const same = (a: string, b: string) => a.toLowerCase() === b.toLowerCase()

/** The service's longest excerpt of a domain: one line. */
const SUMMARY_MAX = 160

/** A domain's excerpt: the first paragraph of its text, plain, on one line, cut at a word. */
export function summaryOf(text: string): string {
  const line = excerptOf(text).replace(/\s+/g, ' ').trim()
  if ([...line].length <= SUMMARY_MAX) return line
  const cut = line.slice(0, SUMMARY_MAX - 1)
  return `${cut.slice(0, Math.max(cut.lastIndexOf(' '), 1)).trimEnd()}…`
}

/** A new domain's id from its name, as the domains' ids are made: "Customer value" is customer_value. */
export function freeAreaId(name: string, taken: ReadonlySet<string>): string {
  const slug = name
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
  const base = (/^[a-z][a-z0-9_]/.test(slug) ? slug : `area_${slug || 'domain'}`)
    .slice(0, 36)
    .replace(/_+$/, '')
  let id = base
  for (let n = 2; taken.has(id); n++) id = `${base}_${n}`
  return id
}

/** Why a setting changed, for the history log: said once, in Settings. */
const BY_SETTINGS = 'Changed in Settings, Agents and access.'

/** How long a read's answer serves the same read again, while nothing was changed since. */
const READ_SHARED_MS = 3000

/**
 * A fetch where identical reads share one request: the shell starts its reads at once, a page then
 * reads its own, and several of them need the same people, domains or Inbox. A read in flight, or
 * answered in the last few seconds, serves the same read again, each caller with its own copy of
 * the answer. Any change (anything but a GET) starts afresh when it is sent and again when it settles, and a read
 * that was in flight meanwhile is never kept, so a read after it sees it.
 */
export function sharedReads(
  send: typeof globalThis.fetch,
  now: () => number = () => Date.now(),
): typeof globalThis.fetch {
  const recent = new Map<string, { answer: Promise<Response>; at: number; generation: number }>()
  let generation = 0
  const forget = (url: string, entry: object) => {
    if (recent.get(url) === entry) recent.delete(url)
  }
  return (input, init) => {
    const request = new Request(input, init)
    if (request.method !== 'GET') {
      generation++
      recent.clear()
      const settled = () => {
        generation++
        recent.clear()
      }
      const written = send(request)
      written.then(settled, settled)
      return written
    }
    const known = recent.get(request.url)
    if (known && known.generation === generation && now() - known.at < READ_SHARED_MS) {
      return known.answer.then((r) => r.clone())
    }
    const answer = send(request).then((response) => {
      // Only an answer that worked serves again; a refusal or a failure is asked again.
      if (!response.ok) forget(request.url, entry)
      return response
    })
    const entry = { answer, at: now(), generation }
    answer.catch(() => forget(request.url, entry))
    recent.set(request.url, entry)
    return answer.then((r) => r.clone())
  }
}

export function createHttpApi({ baseUrl, fetch, shelf }: HttpApiOptions): HeedApi {
  const direct: typeof globalThis.fetch = fetch ?? ((input, init) => globalThis.fetch(input, init))
  const shared = sharedReads(direct)
  const link = new OpenAPILink<CallContext>(routes as unknown as AnyContractRouter, {
    url: baseUrl,
    headers: ({ context }) => context.headers ?? {},
    fetch: (request, init, { context }) =>
      context.posted ? direct(request, init) : shared(request, init),
  })
  const client: ContractRouterClient<Contract, CallContext> = createORPCClient(link)

  /** The token of the latest session read; every change sends it. */
  let csrfToken: string | undefined
  /** Who is signed in, as the latest session read says. */
  let me: { id: string; name: string; admin: boolean } | undefined
  /** Who the sign-in offers, by name, so a name signs in as that person's address. */
  let offered: { name: string; email: string }[] = []
  /** What a review's decisions need, by the card it is reviewed from. */
  const refs = new Map<string, SheetRef>()
  /** The retry key of each change still waiting for an answer. */
  const pendingKeys = new Map<string, string>()
  /** The suggestions sent from the editor this visit: they wait, visibly, on the item and in the Inbox. */
  let sent: Sent[] = []
  /** The items published this visit, and when, in words: the item says so on its page. */
  let published: Record<string, string> = {}
  /** The service's today and how far it is from the clock's day, as the last index read them. */
  let calendar = { today: new Date().toISOString().slice(0, 10), shift: 0 }
  /**
   * The live vocabulary's words and the terms written in Definitions, read once a session and again
   * after a term changes: a scope and a mention are named by them.
   */
  let words: Promise<Words> | undefined
  /** The topics Observability listed, by id, so the answer panel can name what it replays. */
  const listedTopics = new Map<string, ReplayTopic>()

  async function read<T>(call: () => Promise<T>): Promise<T> {
    try {
      return await call()
    } catch (error) {
      throw toApiError(error)
    }
  }

  async function session() {
    const current = await read(() => client.auth.session())
    csrfToken = current.csrfToken
    me = {
      id: current.person.id,
      name: current.person.name,
      admin: current.person.permissions.roles.includes('administrator'),
    }
    return { ...current, me }
  }
  const signedIn = async () => me ?? (await session()).me

  /**
   * A change. Its retry key stays the same for the same operation and input until the service
   * answers, so a change sent again after no answer is applied once.
   */
  async function write<T>(
    operation: string,
    input: unknown,
    call: (options: { context: CallContext }) => Promise<T>,
  ): Promise<T> {
    const id = `${operation} ${canonicalJson(JSON.parse(JSON.stringify(input ?? null)))}`
    const key = pendingKeys.get(id) ?? randomKey()
    pendingKeys.set(id, key)
    const send = (token: string) =>
      call({ context: { headers: { 'x-heed-csrf': token, 'idempotency-key': key } } })
    try {
      let result: T
      try {
        result = await send(csrfToken ?? (await session()).csrfToken)
      } catch (error) {
        if (!csrfRefused(error)) throw error
        result = await send((await session()).csrfToken)
      }
      pendingKeys.delete(id)
      // A term written, renamed, moved or deleted changes the words a mention is named by.
      if (operation.startsWith('terms.') || operation === 'decisions.undo') words = undefined
      return result
    } catch (error) {
      const failure = toApiError(error)
      if (!failure.retryable) pendingKeys.delete(id)
      throw failure
    }
  }

  /**
   * A read the service takes as a POST, so a question's words travel in the body and never in an
   * address: like a change, it carries the session's token, but needs no retry key.
   */
  async function readPosted<T>(call: (options: { context: CallContext }) => Promise<T>) {
    const send = (token: string) =>
      read(() => call({ context: { headers: { 'x-heed-csrf': token }, posted: true } }))
    try {
      return await send(csrfToken ?? (await session()).csrfToken)
    } catch (error) {
      if (!csrfRefused(error)) throw error
      return send((await session()).csrfToken)
    }
  }

  const asSession = (name: string): Session => ({ user: name, install: 'normal', fresh: false })

  /** Everyone the comments may name, both ways: by id, and by name for a mention. */
  async function readPeople(): Promise<People> {
    const people = await read(() => client.people.list())
    const name = new Map(people.map((p) => [p.id, p.name]))
    const id = new Map(people.map((p) => [p.name, p.id]))
    return { name: (personId) => name.get(personId) ?? 'Someone', idOf: (n) => id.get(n) }
  }

  /** The people and the domains, read beside an answer that names them by id. */
  async function readPeopleAndAreas() {
    const [people, areas, who] = await Promise.all([
      read(() => client.people.list()),
      read(() => client.areas.list()),
      signedIn(),
    ])
    return { listed: { people, areas }, workspace: workspaceOf({ people, areas, me: who }) }
  }

  /** Who the answers name by id: the people and the domains, read beside them. */
  async function readNames(): Promise<Names> {
    const { people, areas } = (await readPeopleAndAreas()).listed
    const name = new Map(people.map((p) => [p.id, p.name]))
    const owners = new Map(areas.map((a) => [a.id, a.ownerIds]))
    const person = (id: string) => name.get(id) ?? 'Someone'
    return { person, domainOwners: (areaId) => (owners.get(areaId) ?? []).map(person) }
  }

  /** The metrics and dimensions the catalogue lists, the terms written here, and who wrote them. */
  async function readGlossary() {
    const [catalogue, { terms }, people] = await Promise.all([
      read(() => client.catalogue.list()),
      read(() => client.terms.list()),
      readPeople(),
    ])
    return {
      terms,
      definitions: [...definitionsOf(catalogue.terms), ...termDefinitionsOf(terms, people.name)],
      /** What a name means on the service: a metric's or a dimension's key, or a term's id. */
      refOf(name: string) {
        const key = catalogue.terms.find((t) => same(t.name, name))?.key
        const term = terms.find((t) => same(t.name, name))
        const ref = key ?? (term ? `term:${term.id}` : undefined)
        if (!ref) throw new ApiError('not-found', `“${name}” isn't in Definitions any more.`)
        return ref
      },
      /** The terms written here with these names; a synced definition is never one. */
      idsOf: (names: readonly string[]) =>
        terms.filter((t) => names.some((n) => same(n, t.name))).map((t) => t.id),
      /** A synced definition's history: what its tool says now, as of its last change there. */
      syncedHistory(d: Definition): Version[] {
        const source = catalogue.terms.find((t) => same(t.name, d.name))
        const at =
          source?.definition?.changedAt ?? source?.shelf.lastUpdated ?? `${calendar.today}T00:00`
        const tool = d.tool ?? source?.definition?.tool ?? 'its tool'
        return [
          {
            v: 1,
            who: tool,
            on: serviceDay(at, calendar.shift),
            kind: 'synced',
            summary: `Read from ${tool}.`,
            field: 'Definition',
            before: '',
            after: d.definition,
          },
        ]
      },
    }
  }

  /** A change to many terms: its Undo, or why none of them changed. */
  const undoOf = (done: { undo: string | null; skipped: { message: string }[] }) => {
    if (!done.undo)
      throw new ApiError('conflict', done.skipped[0]?.message ?? 'None of them could be changed.')
    return { undo: done.undo }
  }

  /* ---------- Context ---------- */

  const readWords = () =>
    (words ??= Promise.all([read(() => client.vocabulary.get()), read(() => client.terms.list())])
      .then(([vocabulary, { terms }]) => wordsOf(vocabulary, terms))
      .catch((error: unknown) => {
        words = undefined
        throw error
      }))

  /** Every draft of a context item the person may read: never published, never sent. */
  async function readDrafts(): Promise<ProposalRecord[]> {
    const rows: ProposalRecord[] = []
    for (let offset = 0; ; offset += 100) {
      const page = await read(() => client.proposals.list({ state: 'draft', limit: 100, offset }))
      rows.push(...page.rows.filter((p) => p.subject === 'item'))
      if (offset + page.rows.length >= page.total || !page.rows.length) return rows
    }
  }

  /** Every context item the person may read, and the drafts, with what the index says of them. */
  async function contextRows() {
    const [index, drafts, names, vocabulary] = await Promise.all([
      read(() => client.library.index()),
      readDrafts(),
      readNames(),
      readWords(),
    ])
    calendar = { today: index.today, shift: dayShiftOf(index) }
    return {
      index,
      names,
      items: [
        ...factsOf(index.items, names),
        ...drafts.map((d) => factOfDraft(d, names, vocabulary)),
      ],
    }
  }

  /** A published item's page, or a draft's; null for anything else. */
  async function itemPage(id: string) {
    const [names, vocabulary] = await Promise.all([readNames(), readWords()])
    if (isItemId(id)) {
      const page = await orNull(() => read(() => client.items.page({ id })))
      return page ? itemPageOf(page, names, vocabulary, calendar.shift) : null
    }
    if (!isUuid(id)) return null
    const proposal = await orNull(() => read(() => client.proposals.get({ id })))
    return proposal?.subject === 'item' && proposal.state === 'draft'
      ? { item: factOfDraft(proposal, names, vocabulary), history: [] as Version[] }
      : null
  }

  /**
   * What the editor publishes in one step, or sends to the owners: only what it changes from the
   * item as the service has it, or the whole of a new one. The person's own draft is finished and
   * sent as itself; someone else's draft stays theirs, and what was written from it goes as new.
   */
  async function publishFromEditor(
    fact: Fact,
    isNew: boolean,
    relations: Record<string, Relation> = {},
  ) {
    const [vocabulary, who] = await Promise.all([readWords(), signedIn()])
    const started = !isNew && isUuid(fact.id) ? await readDraft(fact.id) : null
    const own = started?.proposerId === who.id ? started : null
    const itemId = isNew ? undefined : started ? (started.itemId ?? undefined) : fact.id
    const before = itemId && !own ? (await itemPage(itemId))?.item : undefined
    if (!isNew && !started && !before)
      throw new ApiError('not-found', "This context item isn't in Context any more.")
    const answered = Object.entries(relations).map(([id, relation]) => ({
      itemId: id,
      relation: relation === 'disagree' ? ('disagrees' as const) : relation,
    }))
    const input = {
      draft: draftOf(fact, vocabulary, calendar.today, before),
      ...(own ? { draftId: own.id } : itemId ? { itemId } : {}),
      ...(answered.length ? { relations: answered } : {}),
    }
    return write('items.publish', input, (o) => client.items.publish(input, o))
  }

  /** A draft of a context item, by its proposal; not found once it was sent or deleted. */
  async function readDraft(id: string) {
    const proposal = await read(() => client.proposals.get({ id }))
    if (proposal.subject !== 'item' || proposal.state !== 'draft')
      throw new ApiError('not-found', 'This draft was sent or deleted.')
    return proposal
  }

  /** The person's Inbox as the service has it: needs and all, done and waiting. */
  const readFeed = () => read(() => client.inbox.feed({ tab: 'all' }))

  async function inbox() {
    const [feed, { workspace, listed }, who] = await Promise.all([
      readFeed(),
      readPeopleAndAreas(),
      signedIn(),
    ])
    const byId: Domains = Object.fromEntries(workspace.domains.map((d) => [d.id, d]))
    readGaps(feed)
    const name = new Map(listed.people.map((p) => [p.id, p.name]))
    const shown = inboxOf(feed, who.name, byId, new Date(), (id) => name.get(id) ?? 'Someone')
    // What this visit sent waits as it was sent, until an owner decides; the rest as the feed says.
    const waits = new Set(feed.waiting.map((w) => w.proposalId))
    sent = sent.filter((x) => waits.has(x.id))
    const mine = new Set(sent.map((x) => `waiting:${x.id}`))
    return { ...shown, waiting: shown.waiting.filter((w) => !mine.has(w.id)), sent }
  }

  /** A Not found card's draft, by the draft's id, with its card: the app names the card by the draft. */
  const gaps = new Map<string, { card: string; times: number | null }>()
  const readGaps = (feed: Feed) => {
    for (const c of feed.cards)
      if (c.group === 'gap' && c.draft) gaps.set(c.draft, { card: c.id, times: c.times })
  }

  /**
   * The suggestions the person reviews, open and decided, each under its card's id: a Not found
   * card's draft too. Newest sent first, the order the review steps through.
   */
  async function reviews() {
    const feed: Feed = await readFeed()
    readGaps(feed)
    const drafts = new Set(
      feed.cards.flatMap((c) => (c.group === 'gap' && c.draft ? [c.draft] : [])),
    )
    const wanted = [
      ...[...drafts].map((proposal) => ({ card: proposal, proposal })),
      ...feed.cards.flatMap((c) =>
        c.group === 'suggestion' && !drafts.has(c.proposalId)
          ? [{ card: c.proposalId, proposal: c.proposalId }]
          : [],
      ),
    ]
    // Every sheet in one read, or a few for a long Inbox, rather than one read each: the service
    // leaves out one that went while the list was read.
    const sheets: { card: string; proposal: string; sheet: ReviewSheet }[] = []
    for (let at = 0; at < wanted.length; at += REVIEW_SHEETS_MAX) {
      const part = wanted.slice(at, at + REVIEW_SHEETS_MAX)
      const input = { ids: part.map((w) => w.proposal) }
      const read = await readPosted((o) => client.review.sheets(input, o))
      const byId = new Map(read.sheets.map((sheet) => [sheet.proposal.id, sheet]))
      for (const w of part) {
        const sheet = byId.get(w.proposal)
        if (sheet) sheets.push({ ...w, sheet })
      }
    }
    const sent = (s: ReviewSheet) => s.proposal.submittedAt ?? s.proposal.createdAt
    sheets.sort((a, b) =>
      sent(a.sheet) < sent(b.sheet) ? 1 : sent(a.sheet) > sent(b.sheet) ? -1 : 0,
    )
    for (const s of sheets) refs.set(s.card, refOf(s.sheet))
    const vocabulary = await readWords()
    return sheets.map((s) => reviewOf(s.sheet, s.card, gaps.get(s.card), vocabulary))
  }

  /** What deciding on a review needs, read again when this visit has not read it yet. */
  async function refFor(card: string): Promise<SheetRef> {
    if (!refs.has(card)) await reviews()
    const ref = refs.get(card)
    if (!ref) throw new ApiError('not-found', 'This suggestion no longer waits for a decision.')
    return ref
  }

  /** A decision on a card, by its outcome in the Inbox's words. */
  const decideCard = async ({ card: id, outcome }: { card: string; outcome: string }) => {
    // A Not found card with a draft is named by its draft: its decision is the gap card's.
    const card = gaps.get(id)?.card ?? id
    const action = cardActions[outcome]
    if (!action) throw new ApiError('invalid', `A card can't be decided as “${outcome}”.`)
    const decided = await write('cards.decide', { card, action }, (o) =>
      client.cards.decide({ card, action }, o),
    )
    return { undo: decided.undo }
  }

  /** Publishes a suggestion, or archives what a retirement names: one accept by an owner. */
  const publish = async (id: string, relation?: string | null) => {
    const ref = await refFor(id)
    const relations =
      relation && ref.clashes.length
        ? ref.clashes.map((itemId) => ({
            itemId,
            relation: relation === 'disagree' ? ('disagrees' as const) : (relation as 'replaces'),
          }))
        : undefined
    const input = {
      id: ref.proposalId,
      revision: ref.revision,
      ...(relations ? { relations } : {}),
    }
    const done = await write('review.publish', input, (o) => client.review.publish(input, o))
    // Deciding gives it a new revision: the next decision on it reads it again.
    refs.delete(id)
    return { undo: done.undo }
  }

  /** What the business is about, and its version, for an admin; null for anyone else. */
  async function readAbout(): Promise<{ text: string; version: number } | null> {
    if (!(await signedIn()).admin) return null
    const setting = (await read(() => client.settings.list())).find(
      (x) => x.key === 'business.about',
    )
    return {
      text: typeof setting?.value === 'string' ? setting.value : '',
      version: setting?.version ?? 0,
    }
  }

  /* ---------- Ask ---------- */

  const chats = createChatShelf(shelf ?? browserShelf())
  /** What each question's first answer said, for its chat's line in the history search. */
  const said = new Map<string, string>()
  /** The scope each offered question asks with, by its words, so a click gets its row's state. */
  const offeredScopes = new Map<string, ReadScope>()

  const readVocabulary = () => read(() => client.vocabulary.get())

  /** Asked this week, or nothing while nothing is shared with agents yet. */
  async function readAsked(): Promise<Asked | null> {
    try {
      const asked = await read(() => client.ask.asked())
      for (const e of examplesOf(asked)) offeredScopes.set(e.question.toLowerCase(), e.scope)
      return asked
    } catch (error) {
      if (toApiError(error).status === 412) return null
      throw error
    }
  }

  /** The engine's answer to a question: its steps run on the service, the answer is the last event. */
  async function lookUp(input: { question: string } & Partial<ReturnType<typeof lookupFields>>) {
    const events = await readPosted((o) => client.ask.lookup(input, o))
    let answer: Extract<LookupEvent, { type: 'answer' }>['answer'] | undefined
    // The words a real model wrote from the answer's items, when the service has one.
    let written: string | undefined
    for await (const event of events)
      if (event.type === 'answer') answer = event.answer
      else if (event.type === 'words') written = event.text
    if (!answer) throw new ApiError('unanswered', 'The answer stopped before it was finished.')
    return { answer, written }
  }

  /** The look-up's fields from the @ chips: the metrics and the markets they name. */
  function chipFields(
    scope: { id: string }[] | undefined,
    names: ReturnType<typeof namesOf>,
  ): Partial<ReturnType<typeof lookupFields>> {
    const picked = (kind: string) =>
      (scope ?? []).flatMap((m) =>
        m.id.startsWith(`${kind}:`) ? [m.id.slice(kind.length + 1)] : [],
      )
    const metrics = [...picked('metric'), ...picked('term')].flatMap(
      (n) => names.metricKey(n) ?? [],
    )
    const markets = picked('market').flatMap((n) => names.marketKey(n) ?? [])
    return {
      ...(metrics.length ? { metrics } : {}),
      ...(markets.length
        ? { dimension_filters: [{ dimension: 'dim:market', values: markets }] }
        : {}),
    }
  }

  const ask: HeedApi['ask'] = async ({ question = '', parts, scope, example }) => {
    let words = question
    let offered = offeredScopes.get(question.toLowerCase())
    if (example) {
      const found = examplesOf(await readAsked()).find((e) => e.id === example)
      if (!found) throw new ApiError('not-found', 'This question is not offered any more.')
      words = found.question
      offered = found.scope
    }
    const names = namesOf(await readVocabulary())
    const fields = scope?.length ? chipFields(scope, names) : offered ? lookupFields(offered) : {}
    const extra = {
      ...(parts?.some((p) => typeof p !== 'string') ? { parts } : {}),
      ...(scope?.length ? { scope } : {}),
    }
    try {
      const looked = await lookUp({ question: words, ...fields })
      const answer = answerOf(looked.answer, words, names, extra, looked.written)
      said.set(words.toLowerCase(), answer.text.replace(/\[\d+\]/g, ''))
      return answer
    } catch (error) {
      const failure = toApiError(error)
      // Nothing is shared with agents yet: no context, so nothing applies.
      if (failure.status === 412) return { ...nothingLiveAnswer(words), ...extra }
      // The check could not run: Not checked, which is not the same as nothing written down.
      if (failure.kind === 'failed' || failure.kind === 'unanswered')
        return { ...failedAnswer(words), ...extra }
      throw failure
    }
  }

  /* ---------- people ---------- */

  /** A member of the workspace by name, as People names them. */
  async function memberNamed(name: string) {
    const member = (await read(() => client.members.list())).find((m) => m.name === name)
    if (!member) throw new ApiError('not-found', `${name} isn't in the workspace any more.`)
    return member
  }
  /** An open invite by its address, which People names it by. */
  const inviteTo = async (email: string) =>
    (await read(() => client.invites.list())).find((i) => i.email === email)

  /** Sets a domain's owners by id; false when it would leave the domain without one. */
  async function setOwnerIds(areaId: string, personIds: string[]) {
    const input = { areaId, personIds: [...new Set(personIds)] }
    try {
      await write('areas.setOwners', input, (o) => client.areas.setOwners(input, o))
      return true
    } catch (error) {
      if (toApiError(error).kind === 'conflict') return false
      throw error
    }
  }
  const ownerIdsOf = async (areaId: string) => {
    const area = (await read(() => client.areas.list())).find((a) => a.id === areaId)
    if (!area)
      throw new ApiError('not-found', "We couldn't find this domain. It may have been deleted.")
    return area.ownerIds
  }

  /** What Undo puts back after a removal or a revoked invite, by its token. */
  const peopleUndos = new Map<string, () => Promise<unknown>>()
  const rememberUndo = (work: () => Promise<unknown>) => {
    const token = `people:${randomKey()}`
    peopleUndos.set(token, work)
    return token
  }

  /* ---------- figures in Ask ---------- */

  /** The integrations that read figures, by the app's name for their tool: Cube's is `cube`. */
  const connectorOf = (type: string): ConnectorId | undefined =>
    connectorById(type)?.figures ? (type as ConnectorId) : undefined
  async function figureSources() {
    return (await read(() => client.figures.list())).sources.flatMap((source) => {
      const id = connectorOf(source.type)
      return id ? [{ id, source }] : []
    })
  }
  /** The service's own integration for an app's tool: the first that reads figures for it. */
  async function figureSourceId(id: ConnectorId) {
    const found = (await figureSources()).find((f) => f.id === id)
    if (!found) throw new ApiError('not-found', `${connectorById(id)?.name ?? id} isn't connected.`)
    return found.source.id
  }
  async function setFiguresOf(
    id: ConnectorId,
    change: Omit<Parameters<typeof client.figures.set>[0], 'id'>,
  ) {
    const input = { id: await figureSourceId(id), ...change }
    return write('figures.set', input, (o) => client.figures.set(input, o))
  }
  /** A figure that doesn't fit a context item, as the service files it: its keys and its days. */
  async function reportedFigure(figure: FigureReport | undefined) {
    if (!figure) throw new ApiError('invalid', 'Say which figure does not fit.')
    const days = daysOfDates(figure.dates, localDay(new Date()))
    const names = namesOf(await readVocabulary())
    const metric = names.metricKey(figure.metric)
    if (!days || !metric)
      throw new ApiError('invalid', 'This figure has no metric or days to report.')
    return {
      source: await figureSourceId(figure.source),
      metric,
      values: figure.markets.flatMap((m) => names.marketKey(m) ?? []),
      ...days,
      route: figure.to,
    }
  }

  const wired: Pick<HeedApi, (typeof wiredMethods)[number]> = {
    // Owners set their own domain's owners, admins any (areas.setOwners). Someone invited owns the
    // domains of their invite once they sign in, so their ownership is the invite's.
    setOwner: async ({ name, domain, own }) => {
      if (await inviteTo(name))
        throw new ApiError(
          'invalid',
          `${name} owns the domains of their invite once they sign in. Take the invite back to change it.`,
        )
      const member = await memberNamed(name)
      const current = await ownerIdsOf(domain)
      const next = own ? [...current, member.id] : current.filter((id) => id !== member.id)
      if (!next.length && current.length) return { done: false, last: true }
      return (await setOwnerIds(domain, next)) ? { done: true } : { done: false, last: true }
    },
    setAdmin: async ({ name, admin }) => {
      const input = {
        personId: (await memberNamed(name)).id,
        role: admin ? 'admin' : 'member',
      } as const
      await write('members.setRole', input, (o) => client.members.setRole(input, o))
    },
    // Each new invite's link goes back to whoever invites: Heed sends no email yet.
    invite: async ({ emails, admin, owns }) => {
      const input = {
        emails,
        role: admin ? ('admin' as const) : ('member' as const),
        areaIds: owns,
      }
      const made = await write('invites.create', input, (o) => client.invites.create(input, o))
      return {
        links: made.results.flatMap((r) =>
          r.outcome === 'invited' ? [{ email: r.email, link: r.link }] : [],
        ),
        skipped: made.results.flatMap((r) =>
          r.outcome === 'invited' ? [] : [{ email: r.email, why: r.outcome }],
        ),
      }
    },
    resendInvite: async ({ name }) => {
      const invite = await inviteTo(name)
      if (!invite) throw new ApiError('not-found', `${name} has no open invite any more.`)
      const sent = await write('invites.resend', { id: invite.id }, (o) =>
        client.invites.resend({ id: invite.id }, o),
      )
      return { link: sent.link }
    },
    // What someone did lately: the context they checked last, of what the person may read. An
    // invite not yet taken is nobody in the workspace yet, and has done nothing.
    getActivity: async ({ name }) => {
      const member = (await read(() => client.members.list())).find((m) => m.name === name)
      if (!member) return []
      const { entries } = await read(() => client.members.activity({ personId: member.id }))
      return entries.map((e) => ({ what: `Checked ${e.title}`, when: dateLabel(e.on) }))
    },
    // Removing waits while a domain has them as its only owner: those domains come back to hand
    // over first. Undo brings the person back with the roles the removal ended, or invites again.
    removePerson: async ({ name }) => {
      const invite = await inviteTo(name)
      if (invite) {
        await write('invites.revoke', { id: invite.id }, (o) =>
          client.invites.revoke({ id: invite.id }, o),
        )
        const again = { emails: [invite.email], role: invite.role, areaIds: invite.areaIds }
        return {
          removed: true,
          undo: rememberUndo(() =>
            write('invites.create', again, (o) => client.invites.create(again, o)),
          ),
        }
      }
      const personId = (await memberNamed(name)).id
      // The domains they own alone are the refusal's answer, not a failure.
      const alone = await write('members.remove', { personId }, async (o) => {
        try {
          await client.members.remove({ personId }, o)
          return null
        } catch (error) {
          const data = (error as { data?: { areas?: unknown } }).data
          if (Array.isArray(data?.areas) && data.areas.length) return data.areas as string[]
          throw error
        }
      })
      if (alone) return { removed: false, alone }
      return {
        removed: true,
        undo: rememberUndo(() =>
          write('members.restore', { personId }, (o) => client.members.restore({ personId }, o)),
        ),
      }
    },
    // A domain's owners, its name and its text, as its page sets them (FR-815). Its owners and
    // admins change them; an invited owner is the invite's until they sign in.
    updateDomain: async ({ id, owners, name, text }) => {
      if (owners !== undefined) {
        const members = await read(() => client.members.list())
        const ids = owners.flatMap((o) => members.find((m) => m.name === o)?.id ?? [])
        if (!ids.length && (await ownerIdsOf(id)).length)
          throw new ApiError(
            'conflict',
            'A domain needs an owner. Add another owner first, then take this one off.',
          )
        if (!(await setOwnerIds(id, ids)))
          throw new ApiError(
            'conflict',
            'A domain needs an owner. Add another owner first, then take this one off.',
          )
      }
      const renamed = name?.trim()
      if (!renamed && text === undefined) return
      const area = (await read(() => client.areas.list())).find((a) => a.id === id)
      if (!area)
        throw new ApiError('not-found', "We couldn't find this domain. It may have been deleted.")
      const description = text === undefined ? area.description : text.trim()
      const input = {
        id,
        revision: area.revision,
        ...(renamed && renamed !== area.name ? { name: renamed } : {}),
        // The first paragraph of its text is its excerpt everywhere it is shown.
        summary: text === undefined ? area.summary : summaryOf(description),
        description,
      }
      await write('areas.describe', input, (o) => client.areas.describe(input, o))
    },
    // A new domain from its page: its name, its owners and its text; the service gives it the
    // rest. Its id is made from the name, as the domains' ids are.
    addDomain: async ({ name, owners, text }) => {
      // A deleted domain that history keeps holds its id too.
      const [areas, archived, members] = await Promise.all([
        read(() => client.areas.list()),
        read(() => client.areas.archived()),
        read(() => client.members.list()),
      ])
      const id = freeAreaId(name, new Set([...areas, ...archived].map((a) => a.id)))
      const description = (text ?? '').trim()
      const input = {
        id,
        name: name.trim(),
        summary: summaryOf(description),
        description,
        team: { ownerIds: owners.flatMap((o) => members.find((m) => m.name === o)?.id ?? []) },
      }
      const made = await write('areas.create', input, (o) => client.areas.create(input, o))
      return { id: made.id }
    },
    // Only an empty domain is deleted, never the sandbox: the service says why it won't.
    removeDomain: async ({ id }) => {
      await write('areas.deleteEmpty', { id }, (o) => client.areas.deleteEmpty({ id }, o))
    },
    // A workspace whose setup checklist is unfinished is a new install: the Inbox shows the
    // checklist until it is done (docs/product.md, FR-816).
    getSession: async () => {
      try {
        const { me: who } = await session()
        const setup = await read(() => client.setup.state())
        return { ...asSession(who.name), install: setup.done ? 'normal' : 'new' }
      } catch (error) {
        if (toApiError(error).kind === 'signed-out') {
          me = undefined
          return { user: null, install: 'normal', fresh: false }
        }
        throw error
      }
    },
    listSignInPeople: async () => {
      offered = await read(() => client.auth.people())
      return offered.map((p) => p.name)
    },
    // The local sign-in carries its own fixed header instead of a session's token, which it does
    // not have yet; the answer is the new session and its token.
    signIn: async ({ name }) => {
      if (!offered.length) offered = await read(() => client.auth.people())
      const email = offered.find((p) => p.name === name)?.email
      if (!email) throw new ApiError('not-found', `${name} can't sign in here.`)
      const signed = await read(() =>
        client.auth.signIn({ email }, { context: { headers: { 'x-heed-csrf': 'dev-sign-in' } } }),
      )
      csrfToken = signed.csrfToken
      me = {
        id: signed.person.id,
        name: signed.person.name,
        admin: signed.person.permissions.roles.includes('administrator'),
      }
      refs.clear()
      sent = []
      published = {}
      words = undefined
      return asSession(signed.person.name)
    },
    getSignInMethod: async () => {
      const method = await read(() => client.auth.methods())
      return method.method === 'oidc' && method.start
        ? {
            kind: 'oidc' as const,
            name: method.name ?? 'your company account',
            start: method.start,
          }
        : { kind: 'picker' as const }
    },
    readInvite: async ({ token }) => {
      try {
        const invite = await read(() => client.invites.lookup({ token }))
        return {
          email: invite.email,
          admin: invite.role === 'admin',
          domains: invite.areas.map((a) => a.name),
        }
      } catch (error) {
        // A link that opens no invite, or isn't one: the same answer.
        const kind = toApiError(error).kind
        if (kind === 'not-found' || kind === 'invalid') return null
        throw error
      }
    },
    // What the business is about is an admin's setting; the setup checklist's steps are read from
    // what exists. Start from the guide fills in the worked example, an outdoor-gear retailer.
    // The people are the workspace's members, Admin or Member, and its open invites.
    getWorkspace: async () => {
      const [{ workspace }, setup, about, members, invites, named] = await Promise.all([
        readPeopleAndAreas(),
        read(() => client.setup.state()),
        readAbout(),
        read(() => client.members.list()),
        read(() => client.invites.list()),
        read(() => client.workspace.get()),
      ])
      const { people, domains } = peopleOf({
        members,
        invites,
        domains: workspace.domains,
        now: new Date(),
      })
      return {
        name: named.name,
        domains,
        people,
        about: about?.text ?? '',
        aboutTemplate: ABOUT_BUSINESS_STARTER,
        setup: { done: Object.fromEntries(setup.steps.map((s) => [s.id, s.done])) },
      }
    },
    setAbout: async ({ text }) => {
      const current = await readAbout()
      if (!current)
        throw new ApiError('forbidden', 'Only an admin says what the business is about.')
      if (current.text === text) return
      const input = {
        key: 'business.about',
        version: current.version,
        value: text,
        reason: 'About our business, written in Settings.',
      }
      await write('settings.set', input, (o) => client.settings.set(input, o))
    },
    // The service reads each step from what exists (setup.state): nothing to mark by hand.
    completeSetupStep: () => Promise.resolve(),
    getVocabulary: async () => {
      const vocabulary = await read(() => client.vocabulary.get())
      const markets = vocabulary.dimensions.find((d) => d.id === 'market')?.values ?? []
      return {
        metrics: vocabulary.metrics.map((m) => ({
          name: m.name,
          group: m.group,
          facts: 0,
          definition: '',
        })),
        dimensions: vocabulary.dimensions.map((d) => ({
          name: d.name,
          values: d.values.map((v) => v.name).join(', '),
          definition: '',
        })),
        markets: markets.map((v) => v.name),
      }
    },
    // What the person opened and the History log are the service's; what this visit published,
    // the item says on its page.
    getLibrary: async () => {
      const [{ index, names, items }, changes] = await Promise.all([
        contextRows(),
        read(() => client.items.changes()),
      ])
      return {
        items,
        published: { ...published },
        viewed: Object.fromEntries(index.items.filter((r) => r.opened).map((r) => [r.id, true])),
        log: logOf(changes, names, calendar.shift),
      }
    },
    contextPage: async () => (await contextRows()).items,
    itemPage: ({ id }) => itemPage(id),
    getItemHistory: async ({ id }) => (await itemPage(id))?.history ?? [],
    // From an item or a synced definition. A draft is not served, so it has nothing to follow; a
    // term written here has no links on the service yet.
    getRelated: async ({ id }) => {
      const { kind, key } = parseMentionId(id)
      const words = await readWords()
      const definition = kind === 'metric' || kind === 'dimension' ? words.keyOf(key) : undefined
      const found =
        kind === 'context' && isItemId(key)
          ? await orNull(() => read(() => client.items.related({ id: key })))
          : definition && definition.kind === (kind === 'metric' ? 'metric' : 'dim')
            ? await orNull(() => read(() => client.definitions.related({ key: definition.key })))
            : null
      return found
        ? { links: linksOfRelated(found, words), following: found.following }
        : { links: [], following: true }
    },
    restoreAsDraft: async ({ id, v }) => {
      const page = await orNull(() => read(() => client.items.page({ id })))
      if (!page) throw new ApiError('not-found', "This context item isn't in Context any more.")
      const version = versionAt(page.history, v)
      if (version === null)
        throw new ApiError(
          'invalid',
          'That change made no version of its own: its words are the one before.',
        )
      const input = { id, version }
      const restored = await write('items.restoreAsDraft', input, (o) =>
        client.items.restoreAsDraft(input, o),
      )
      return { id: restored.proposalId }
    },
    // A draft is no item the service keeps reads of: it is opened only once it is published.
    markViewed: async ({ id }) => {
      if (!isItemId(id)) return
      await write('items.markRead', { id }, (o) => client.items.markRead({ id }, o))
    },
    // The one change made in place is a check that it is still true, by an owner or an admin,
    // made where the person reads the item: Mark as checked, for that one item.
    editItem: async ({ id, patch }) => {
      if (patch.status !== 'Live' || !patch.checkedBy)
        throw new ApiError(
          'invalid',
          'Only a check that it is still true changes an item in place.',
        )
      await write('items.markRead', { id }, (o) => client.items.markRead({ id }, o))
      const input = { action: 'check' as const, rows: [id] }
      const done = await write('items.bulkApply', input, (o) => client.items.bulkApply(input, o))
      const left = [...done.failed, ...done.skipped][0]
      if (left) throw new ApiError('conflict', left.message)
    },
    // A Not found card closes when its own draft is decided, and the setup checklist reads its
    // first item from what exists: neither needs saying here.
    saveItem: async ({ fact, isNew, relations }) => {
      const done = await publishFromEditor(fact, isNew, relations)
      if (!done.published) return { id: isNew ? done.proposalId : fact.id }
      published[done.itemId] = 'just now'
      return { id: done.itemId }
    },
    draftFromText: async ({ text }) => {
      const [drafted, names, vocabulary] = await Promise.all([
        write('drafts.fromText', { text }, (o) => client.drafts.fromText({ text }, o)),
        readNames(),
        readWords(),
      ])
      return factOfReadDraft(drafted.draft, names, vocabulary)
    },
    applyBulk: async (change) => {
      const rows = [...new Set([...Object.keys(change.patches), ...change.remove])]
      const personId = change.person ? (await readPeople()).idOf(change.person) : undefined
      if (change.person && !personId)
        throw new ApiError('not-found', `${change.person} isn't in this workspace.`)
      const input = {
        action: bulkActions[change.action],
        rows,
        ...(change.domain ? { areaId: change.domain } : {}),
        ...(change.kind ? { kind: change.kind } : {}),
        ...(personId ? { personId } : {}),
      }
      const done = await write('items.bulkApply', input, (o) => client.items.bulkApply(input, o))
      // A row the service left alone where the screen expected it to act is one that didn't go
      // through: it stays ticked, to try again. With nothing done there is nothing to undo.
      return {
        done: done.done,
        failed: [...done.failed, ...done.skipped].map((r) => r.id),
        undo: done.undo ?? '',
      }
    },
    // Owners publish in one step; a suggestion waits for them, on the item and in the Inbox.
    sendSuggestion: async ({ sent: suggestion, fact }) => {
      const done = await publishFromEditor(fact, !suggestion.factId)
      if (done.published) {
        published[done.itemId] = 'just now'
        return { id: done.itemId }
      }
      sent = [{ ...suggestion, id: done.proposalId }, ...sent]
      return { id: done.proposalId }
    },
    withdrawSuggestion: async ({ id }) => {
      const proposal = await read(() => client.proposals.get({ id: id.replace(/^waiting:/, '') }))
      const input = {
        id: proposal.id,
        revision: proposal.revision,
        reason: 'Withdrawn by the person who sent it.',
      }
      await write('proposals.withdraw', input, (o) => client.proposals.withdraw(input, o))
      sent = sent.filter((x) => x.id !== proposal.id)
    },
    getDefinitions: async () => (await readGlossary()).definitions,
    definitionsPage: async () => (await readGlossary()).definitions,
    definitionPage: async ({ name }) =>
      (await readGlossary()).definitions.find((d) => same(d.name, name)) ?? null,
    getDefinitionHistory: async ({ name }) => {
      const glossary = await readGlossary()
      const term = glossary.terms.find((t) => same(t.name, name))
      if (term) {
        const [versions, people] = await Promise.all([
          read(() => client.terms.history({ id: term.id })),
          readPeople(),
        ])
        return termHistoryOf(versions, people.name, calendar.shift)
      }
      const synced = glossary.definitions.find((d) => same(d.name, name))
      return synced ? glossary.syncedHistory(synced) : []
    },
    saveTerm: async ({ previous, term }) => {
      if (term.synced) return
      const glossary = await readGlossary()
      const fields = {
        name: term.name,
        ...(term.sameAs ? { sameAs: glossary.refOf(term.sameAs) } : { meaning: term.definition }),
        areaId: term.domain ?? null,
      }
      if (!previous) {
        await write('terms.create', fields, (o) => client.terms.create(fields, o))
        return
      }
      const was = glossary.terms.find((t) => same(t.name, previous))
      if (!was) throw new ApiError('not-found', `There is no term called “${previous}”.`)
      const input = { id: was.id, revision: was.revision, ...fields }
      await write('terms.update', input, (o) => client.terms.update(input, o))
    },
    addSynonym: async ({ target, word }) => {
      const name = word.trim().replace(/\s+/g, ' ')
      if (!name) return { ok: false, why: 'empty', reason: 'Type a word.' }
      const input = { name, sameAs: (await readGlossary()).refOf(target) }
      // A word that already means something is the synonym box's answer, not a failure.
      const refused = await write('terms.create', input, async (o) => {
        try {
          await client.terms.create(input, o)
          return null
        } catch (error) {
          const refusal = refusalOf(error)
          if (refusal) return refusal
          throw error
        }
      })
      return refused ?? { ok: true, created: true }
    },
    removeTerm: async ({ name }) => {
      const ids = (await readGlossary()).idsOf([name])
      if (!ids.length) throw new ApiError('not-found', `There is no synonym called “${name}”.`)
      const input = { ids }
      return undoOf(await write('terms.delete', input, (o) => client.terms.delete(input, o)))
    },
    // What was deleted, and by whom, is the service's to keep: the screen's log entry is its own.
    deleteTerms: async ({ names }) => {
      const input = { ids: (await readGlossary()).idsOf(names) }
      if (!input.ids.length)
        throw new ApiError('not-found', 'None of these terms is here any more.')
      return undoOf(await write('terms.delete', input, (o) => client.terms.delete(input, o)))
    },
    moveTerms: async ({ names, domain }) => {
      const input = { ids: (await readGlossary()).idsOf(names), areaId: domain }
      if (!input.ids.length)
        throw new ApiError('not-found', 'None of these terms is here any more.')
      return undoOf(await write('terms.move', input, (o) => client.terms.move(input, o)))
    },
    searchAll: async ({ q }) =>
      q.trim() ? hitsOf(await read(() => client.search.all({ q }))) : emptyHits(),
    getComments: async () => {
      const [{ threads }, people, who] = await Promise.all([
        read(() => client.comments.list({})),
        readPeople(),
        signedIn(),
      ])
      return commentsOf(threads, people, who.name, new Date())
    },
    postComment: async ({ subject, content, parentId, returned }) => {
      // A returned note is written by the return itself (returnReview), never on its own.
      if (returned)
        throw new ApiError('invalid', 'A note is returned with its suggestion, from the review.')
      const input = {
        subject,
        body: bodyToService(content, await readPeople()),
        ...(parentId ? { parentId } : {}),
      }
      const posted = await write('comments.create', input, (o) => client.comments.create(input, o))
      return { id: posted.id }
    },
    reactToComment: async ({ subject, id, emoji }) => {
      const input = { subject, commentId: id, emoji }
      await write('reactions.toggle', input, (o) => client.reactions.toggle(input, o))
    },
    reactToSubject: async ({ subject, emoji }) => {
      const input = { subject, emoji }
      await write('reactions.toggle', input, (o) => client.reactions.toggle(input, o))
    },
    editComment: async ({ id, content }) => {
      const input = { id, body: bodyToService(content, await readPeople()) }
      await write('comments.edit', input, (o) => client.comments.edit(input, o))
    },
    removeComment: async ({ id }) => {
      await write('comments.remove', { id }, (o) => client.comments.remove({ id }, o))
    },
    withdrawWithComment: async ({ id, withdrew }) => {
      const input = { id, withdrew }
      await write('comments.withdraw', input, (o) => client.comments.withdraw(input, o))
      // The review now reads it as taken back, or not.
      refs.clear()
    },
    // Only a suggestion's review and a context item hold a thread on the service: a card of
    // another kind (a check, a report) has none to open.
    markThreadSeen: async ({ subject }) => {
      if (!/^(review:[0-9a-f-]{36}|context:itm_[a-z0-9]{8,16})$/.test(subject)) return
      await write('threads.markRead', { subject }, (o) => client.threads.markRead({ subject }, o))
    },
    markMentionSeen: async ({ subject }) => {
      await write('comments.markMentionsRead', { subject }, (o) =>
        client.comments.markMentionsRead({ subject }, o),
      )
    },
    signOut: async () => {
      const token = csrfToken ?? (await session()).csrfToken
      await read(() =>
        client.auth.signOut(undefined, { context: { headers: { 'x-heed-csrf': token } } }),
      )
      csrfToken = undefined
      me = undefined
      refs.clear()
      sent = []
      published = {}
      words = undefined
    },

    // The Inbox and the review
    getInbox: inbox,
    inboxPage: inbox,
    getReviews: reviews,
    markOpened: async ({ ids }) => {
      // A suggestion's card is named by its bare proposal id; the service names it `proposal:<id>`.
      // A Not found card named by its draft: opening it opens both.
      const cards = ids.flatMap((id) =>
        isUuid(id)
          ? [`proposal:${id}`, ...(gaps.has(id) ? [gaps.get(id)!.card] : [])]
          : /^(proposal|gap|feedback|report|check|mention):/.test(id)
            ? [id]
            : [],
      )
      if (!cards.length) return
      await write('cards.markRead', { cards }, (o) => client.cards.markRead({ cards }, o))
    },
    markReviewed: async ({ id }) => {
      const ref = await refFor(id)
      if (!ref.itemVersionId) return
      const input = { id: ref.proposalId, itemVersionId: ref.itemVersionId }
      await write('review.markRead', input, (o) => client.review.markRead(input, o))
    },
    decideCard,
    completeCard: decideCard,
    // A Not found card's draft also saves its question, unless the person said not to (FR-526);
    // Undo takes both back. The publish stands if the question cannot be saved.
    publishReview: async ({ id, relation, saveQuestion }) => {
      const { gap } = await refFor(id)
      const done = await publish(id, relation)
      if (!gap || saveQuestion === false) return done
      const input = {
        areaId: gap.areaId,
        question: `What happened to ${gap.scope}?`,
        origin: 'gap' as const,
      }
      const saved = await write('savedQuestions.create', input, (o) =>
        client.savedQuestions.create(input, o),
      ).catch(() => null)
      if (!saved) return done
      return {
        undo: rememberUndo(async () => {
          const token = saved.undo
          await write('decisions.undo', { token }, (o) => client.decisions.undo({ token }, o))
          await write('decisions.undo', { token: done.undo }, (o) =>
            client.decisions.undo({ token: done.undo }, o),
          )
          refs.clear()
        }),
      }
    },
    archiveReview: ({ id }) => publish(id),
    publishReviews: async ({ ids }) => {
      const proposals = await Promise.all(ids.map(async (id) => (await refFor(id)).proposalId))
      const done = await write('review.publishRead', { ids: proposals }, (o) =>
        client.review.publishRead({ ids: proposals }, o),
      )
      for (const id of ids) refs.delete(id)
      if (!done.undo)
        throw new ApiError(
          'conflict',
          done.skipped[0]?.message ?? 'None of them could be published.',
        )
      return { undo: done.undo }
    },
    returnReview: async ({ id, note }) => {
      const ref = await refFor(id)
      const input = {
        id: ref.proposalId,
        revision: ref.revision,
        note: plainOf(note).trim(),
        body: bodyToService(note, await readPeople()),
      }
      const done = await write('review.return', input, (o) => client.review.return(input, o))
      refs.delete(id)
      return { undo: done.undo }
    },
    closeReview: async ({ id }) => {
      const ref = await refFor(id)
      const input = { id: ref.proposalId, revision: ref.revision }
      const done = await write('review.close', input, (o) => client.review.close(input, o))
      refs.delete(id)
      return { undo: done.undo }
    },
    undo: async ({ token }) => {
      // A deleted chat is put back in the browser, where it is kept.
      if (chats.undo(token)) return
      // A removal or a revoked invite is put back by its own call.
      const person = peopleUndos.get(token)
      if (person) {
        peopleUndos.delete(token)
        await person()
        return
      }
      // A change that did nothing has nothing to take back.
      if (!token) return
      await write('decisions.undo', { token }, (o) => client.decisions.undo({ token }, o))
      // What it put back waits again under a new revision.
      refs.clear()
    },
    // The live line's state a review address shows is the mock's own: never on the service.
    getConnectReview: () => Promise.resolve(null),
    // The consent page of an agent's sign-in (FR-403): the request the login server sent the
    // browser here with, and the person's answer, which the service turns into the agent's code.
    getConnectRequest: async ({ id }) => {
      try {
        return await read(() => client.connections.request({ id }))
      } catch (error) {
        // Answered, run out, started in another browser, or no sign-in at all: it has ended.
        const kind = toApiError(error).kind
        if (kind === 'not-found' || kind === 'invalid') return null
        throw error
      }
    },
    answerConnectRequest: (input) =>
      write('connections.decide', input, (o) => client.connections.decide(input, o)),

    // Settings, agents and access. The switches are what everyone signed in may read: the tools on
    // and what is paused. Figures and their data contacts come with the figures (P11a, part 2).
    getSettings: async () => {
      const [connect, stops, who, figured] = await Promise.all([
        read(() => client.connect.get()),
        read(() => client.serving.stops()),
        signedIn(),
        figureSources(),
      ])
      // The tools connected, which only an admin reads: Settings' menu counts them.
      const connected = who.admin
        ? [
            ...new Set(
              (await read(() => client.sources.list())).flatMap((row) => {
                const id = catalogIdOf(row.type)
                return id ? [id] : []
              }),
            ),
          ]
        : []
      return {
        mcpAddress: connect.address,
        ...switchesOf(connect.tools, stops),
        figures: Object.fromEntries(figured.map(({ id, source }) => [id, source.enabled])),
        contacts: Object.fromEntries(
          figured.flatMap(({ id, source }) =>
            source.dataContact ? [[id, source.dataContact.name]] : [],
          ),
        ),
        connected,
      }
    },
    setFigures: async ({ source, on }) =>
      void (await setFiguresOf(source, {
        enabled: on,
        reason: on ? 'Show figures in Ask, switched on.' : 'Show figures in Ask, switched off.',
      })),
    setDataContact: async ({ source, name }) => {
      const member = await memberNamed(name)
      await setFiguresOf(source, {
        dataContactId: member.id,
        reason: 'The data contact, chosen on the integration.',
      })
    },
    setFigureConnection: async ({ source, endpoint, token }) =>
      void (await setFiguresOf(source, {
        endpoint,
        token,
        reason: 'Where figures are read, set on the integration.',
      })),
    readFigure: async ({ metric, markets, dates, state, sources }) => {
      if (!metric || state === 'failed') return null
      const days = daysOfDates(dates, localDay(new Date()))
      if (!days) return null
      const names = namesOf(await readVocabulary())
      const key = names.metricKey(metric)
      const values = markets.flatMap((m) => names.marketKey(m) ?? [])
      // A metric or a market Definitions doesn't name has no figure the service could read.
      if (!key || values.length !== markets.length) return null
      const items = (sources ?? []).filter(isItemId)
      const input = { metric: key, values, ...days, ...(items.length ? { items } : {}) }
      const figure = await readPosted((o) => client.figures.read(input, o))
      return figureViewOf(
        figure,
        { metric, markets, ...(dates ? { dates } : {}) },
        connectorOf,
        new Date(),
      )
    },
    // What the figures read: how each integration that reads figures is reached.
    getIntegrations: async () => ({
      figureConnections: Object.fromEntries(
        (await figureSources()).map(({ id, source }) => [
          id,
          {
            endpoint: source.connection?.endpoint ?? null,
            host: source.connection?.declaredHost ?? null,
            secretSet: source.connection?.tokenSet ?? false,
            contact: source.dataContact?.name ?? '',
          },
        ]),
      ),
      warehouseHas: [],
    }),
    // Settings › Integrations: the sources the service reads, each with how it is (CON-104).
    integrationsPage: async () => {
      const [rows, types] = await Promise.all([
        read(() => client.sources.list()),
        read(() => client.sources.types()),
      ])
      return integrationsOf(rows, types, new Date())
    },
    integrationPage: async ({ id }) => {
      const row = (await read(() => client.sources.list())).find((r) => r.id === id)
      if (!row) return null
      const [activity, types, settings] = await Promise.all([
        read(() => client.sources.activity({ id })),
        read(() => client.sources.types()),
        // The server's own sources are configured where it runs: their settings are not read here.
        row.origin === 'workspace' ? orNull(() => client.sources.get({ id })) : null,
      ])
      const manifest = types.find((t) => t.manifest.id === row.type)?.manifest
      return sourcePageOf(row, activity, settings, manifest, new Date())
    },
    // Read again: due now, at the job's next turn (CON-115).
    readIntegration: async ({ id }) => {
      await write('sources.read', { id }, (o) => client.sources.read({ id }, o))
    },
    pauseIntegration: async ({ id, paused }) => {
      const input = {
        id,
        paused,
        reason: paused
          ? 'Paused reading, in Settings, Integrations.'
          : 'Resumed reading, in Settings, Integrations.',
      }
      await write('sources.pause', input, (o) => client.sources.pause(input, o))
    },
    // The connect flow on the connectors' manifests (CON-112): a source an admin added, to
    // change; or a tool of the catalog, to connect. The server's own sources are its operator's.
    connectForm: async ({ id }) => {
      const [rows, types] = await Promise.all([
        read(() => client.sources.list()),
        read(() => client.sources.types()),
      ])
      const row = rows.find((r) => r.id === id)
      const type = row ? row.type : connectorOfCatalog(id as ConnectorId)
      const manifest = types.find((t) => t.manifest.id === type)?.manifest
      if (!manifest || row?.origin === 'server') return null
      const settings = row ? await read(() => client.sources.get({ id })) : null
      return connectFormOf(manifest, settings)
    },
    // Keeps nothing and changes nothing: a POST only because the settings hold secrets.
    testIntegration: async ({ connector, source, config, secrets }) => {
      const type = connectorOfCatalog(connector)
      if (!type) throw new ApiError('not-found', "This tool can't be connected here.")
      const input = {
        ...(source ? { id: source } : {}),
        type,
        config: configOf(config),
        secrets: secretsOf(secrets),
      }
      try {
        return connectTestOf(await readPosted((o) => client.sources.test(input, o)))
      } catch (error) {
        // Settings the service refuses (an address that is not https, a folder outside the
        // repository) fail the test, in its words.
        if (error instanceof ApiError && error.kind === 'invalid')
          return { ok: false, steps: [], scopes: [], failure: error.message }
        throw error
      }
    },
    // The source is named after its tool; the service reads it at once (CON-115).
    connectIntegration: async ({ connector, config, secrets, chosen, reason }) => {
      const type = connectorOfCatalog(connector)
      const manifest = (await read(() => client.sources.types())).find(
        (t) => t.manifest.id === type,
      )?.manifest
      if (!type || !manifest) throw new ApiError('not-found', "This tool can't be connected here.")
      const input = {
        type,
        name: manifest.tool,
        config: configOf(config),
        secrets: secretsOf(secrets),
        scopes: scopesOf(chosen),
        reason,
      }
      // The retry key names the secrets, never their values.
      const keyed = { ...input, secrets: Object.keys(input.secrets).sort() }
      const added = await write('sources.add', keyed, (o) => client.sources.add(input, o))
      return { id: added.id, firstRead: null }
    },
    changeIntegration: async ({ id, revision, config, secrets, chosen, reason }) => {
      const before = await read(() => client.sources.get({ id }))
      const input = {
        id,
        revision,
        name: before.name,
        config: changedConfigOf(before.config, config),
        secrets: secretsOf(secrets),
        scopes: scopesOf(chosen),
        reason,
      }
      const keyed = { ...input, secrets: Object.keys(input.secrets).sort() }
      await write('sources.update', keyed, (o) => client.sources.update(input, o))
    },
    disconnectIntegration: async ({ id }) => {
      const input = { id, reason: 'Disconnected, in Settings, Integrations.' }
      await write('sources.remove', input, (o) => client.sources.remove(input, o))
    },
    setLinks: async ({ on }) => {
      const input = { tool: 'get_related', enabled: on, reason: BY_SETTINGS }
      await write('tools.set', input, (o) => client.tools.set(input, o))
    },
    setTool: async ({ name, on }) => {
      const input = { tool: name, enabled: on, reason: BY_SETTINGS }
      await write('tools.set', input, (o) => client.tools.set(input, o))
    },
    // One domain is paused at a time on this page: pausing another lets the one before go on.
    setPause: async (change) => {
      const stop = (input: { scope: 'all' | 'area'; areaId?: string; on: boolean }) => {
        const sent = { ...input, reason: 'Pause sharing, in Settings, Agents and access.' }
        return write('serving.setStop', sent, (o) => client.serving.setStop(sent, o))
      }
      if ('all' in change) return void (await stop({ scope: 'all', on: change.all }))
      const paused = (await read(() => client.serving.stops())).flatMap((s) =>
        s.scope === 'area' && s.areaId ? [s.areaId] : [],
      )
      for (const areaId of paused)
        if (areaId !== change.domain) await stop({ scope: 'area', areaId, on: false })
      if (change.domain && !paused.includes(change.domain))
        await stop({ scope: 'area', areaId: change.domain, on: true })
    },
    // An admin sees everyone's agents; anyone else their own.
    listAgentConnections: async () => {
      const who = await signedIn()
      const rows = who.admin
        ? await read(() => client.agentConnections.list())
        : await read(() => client.connections.list())
      return connectedOf(rows, who.name, new Date())
    },
    // Every connection of that agent for that person ends at once, or the one access key, with the
    // reason the log keeps.
    revokeAgentConnection: async ({ agent, who, key }) => {
      const me = await signedIn()
      if (key) {
        if (!me.admin) throw new ApiError('forbidden', 'Only an admin revokes an access key.')
        const input = { id: key, reason: 'Access key revoked in Settings, Agents and access.' }
        await write('agentConnections.disconnect', input, (o) =>
          client.agentConnections.disconnect(input, o),
        )
        return
      }
      if (me.admin) {
        const ended = (await read(() => client.agentConnections.list())).filter(
          (c) => c.kind === 'agent' && c.clientName === agent && c.person.name === who,
        )
        for (const c of ended) {
          const input = { id: c.id, reason: 'Revoked in Settings, Agents and access.' }
          await write('agentConnections.disconnect', input, (o) =>
            client.agentConnections.disconnect(input, o),
          )
        }
        return
      }
      if (who !== me.name)
        throw new ApiError('forbidden', 'Only an admin revokes the agents of others.')
      for (const c of (await read(() => client.connections.list())).filter(
        (x) => x.clientName === agent,
      ))
        await write('connections.disconnect', { id: c.id }, (o) =>
          client.connections.disconnect({ id: c.id }, o),
        )
    },
    // The key is in this answer only: the service keeps its digest, and this binding keeps nothing.
    createAccessKey: async () => {
      const { key } = await write('accessKeys.create', null, (o) =>
        client.accessKeys.create(undefined, o),
      )
      return { key }
    },
    checkConnect: async ({ since }) => {
      const answer = await read(() =>
        client.connect.pending({ since: new Date(since).toISOString() }),
      )
      return { state: answer.state, ...(answer.agent ? { agent: answer.agent } : {}) }
    },

    // Settings, Advanced: the tuning settings, what was deleted, the history log, the jobs and
    // the editions, as the service has them.
    advancedPage: async () => {
      const now = new Date()
      const [settings, drafts, terms, history, changes, operations, editions, people, areas] =
        await Promise.all([
          read(() => client.settings.list()),
          read(() => client.items.deleted()),
          read(() => client.terms.deleted()),
          read(() => client.audit.search({ limit: 20 })),
          read(() => client.items.changes()),
          // The job runner answers on its own: a page without it still shows the rest.
          read(() => client.operations.overview()).catch(() => null),
          read(() => client.editions.list({ limit: 3 })),
          readPeople(),
          read(() => client.areas.list()),
        ])
      const domainName = (id: string) => areas.find((a) => a.id === id)?.name ?? id
      return {
        settings: settingsOf(settings, (id) => people.name(id), now),
        deleted: deletedOf(drafts, terms, (id) => (id ? people.name(id) : 'Someone'), now),
        history: historyOf(history.entries, changes, now, {
          domain: domainName,
          person: (id) => people.name(id),
        }),
        jobs: operations ? jobsOf(operations, now) : null,
        editions: editionsOf(editions, now),
      }
    },
    checkHistory: async () => {
      const chain = await read(() => client.audit.verify())
      return { whole: chain.verified, entries: null }
    },
    exportHistory: async () => {
      const lines: string[] = []
      for (let after: number | undefined = undefined; ;) {
        const page = await read(() =>
          client.audit.export({ format: 'jsonl', ...(after === undefined ? {} : { after }) }),
        )
        if (page.content) lines.push(page.content.replace(/\n$/, ''))
        if (page.next === null) break
        after = page.next
      }
      return {
        name: `history-${calendar.today}.jsonl`,
        type: 'application/jsonl',
        content: lines.join('\n'),
      }
    },
    exportContext: async () => {
      const live = (await read(() => client.editions.list({ limit: 20 }))).find((e) => e.live)
      if (!live)
        throw new ApiError('not-found', 'Agents get no context yet, so there is nothing to export.')
      const edition = await read(() => client.editions.export({ label: live.label }))
      return {
        name: `context-${live.label}.json`,
        type: 'application/json',
        content: JSON.stringify(edition, null, 2),
      }
    },

    // Ask: the engine on the live edition, and the person's chats in their browser.
    readQuestion: async ({ question }) => {
      const reading = await readPosted((o) => client.tryIt.read({ question }, o))
      return {
        metric:
          reading.about.find((t) => t.kind === 'metric' || t.kind === 'metric_group')?.name ?? '',
        markets: reading.about
          .filter((t) => t.kind === 'dimension_value' && t.dimension === 'Market')
          .map((t) => t.name),
      }
    },
    ask,
    askedThisWeek: async () => {
      const [asked, vocabulary] = await Promise.all([readAsked(), readVocabulary()])
      return askedWeekOf(asked, namesOf(vocabulary))
    },
    getAskExamples: async () =>
      examplesOf(await readAsked()).map(({ scope: _scope, ...example }) => example),
    listChats: async () => chats.list((await signedIn()).id),
    saveChat: async ({ id, question }) =>
      chats.add((await signedIn()).id, id, question, said.get(question.toLowerCase()) ?? ''),
    renameChat: async ({ id, title }) => chats.rename((await signedIn()).id, id, title),
    deleteChat: async ({ id }) => chats.remove((await signedIn()).id, id),
    // A named report: the question, the part and the words the person sent, with their name.
    reportAnswer: async ({ question, part, sources, what, correction, link, figure }) => {
      const itemId = part === 'answer' || part === 'figure' ? sources[0] : part
      if (!itemId) throw new ApiError('invalid', 'This answer has no context item to report.')
      const input = {
        question,
        itemId,
        part:
          part === 'answer'
            ? ('answer' as const)
            : part === 'figure'
              ? ('figure' as const)
              : ('item' as const),
        what,
        ...(correction?.trim() ? { correction } : {}),
        ...(link?.trim() ? { link: link.trim() } : {}),
        ...(part === 'figure' ? { figure: await reportedFigure(figure) } : {}),
      }
      const sent = await write('reports.create', input, (o) => client.reports.create(input, o))
      return { id: sent.id }
    },
    getMyReports: async () => {
      const now = new Date()
      return (await read(() => client.reports.mine())).reports.map((r) => ({
        id: r.id,
        question: r.question,
        on: reportedOn(new Date(r.at), now),
        ...(r.outcome
          ? { outcome: reportOutcomeWords(r.outcome.kind, new Date(r.outcome.at)) }
          : {}),
      }))
    },

    // Observability: the service discloses every count (FR-614); this binding only names things.
    // Quality and Alerts read their own lists (saved questions, alerts); Alerts with nothing ever
    // raised that the person may read is a page with nothing yet.
    observabilityPage: async ({ section, range, domain, agent }) => {
      const now = new Date()
      if (section === 'overview' || section === 'questions') {
        const family = agent ? familyOf(agent) : undefined
        const view = await read(() =>
          client.obs.agents({
            range,
            ...(domain ? { areaId: domain } : {}),
            ...(family ? { agent: family } : {}),
          }),
        )
        const page = obsAgentsOf(view, range)
        for (const t of [...page.topics, ...page.notFound.topics]) {
          const named = { metric: t.metric, where: t.where, month: t.month }
          listedTopics.set(t.id, { ...named, name: topicNameOf(t, page.markets) })
        }
        return page
      }
      if (section === 'feedback')
        return obsFeedbackOf(
          await read(() => client.obs.feedback({ range, ...(domain ? { areaId: domain } : {}) })),
          range,
          now,
        )
      if (section === 'usage')
        return obsUsageOf(await read(() => client.obs.usage({ range })), range, now)
      if (section === 'alerts') {
        const raised = await read(() => client.alerts.raised({ limit: 1 }))
        return emptyObs(range, raised.length ? 'normal' : 'empty')
      }
      return emptyObs(range)
    },
    replayTopic: async ({ topic, when }) => {
      const named = listedTopics.get(topic)
      if (!named || !isUuid(topic)) return null
      const run = async (at: 'now' | 'before') => {
        try {
          // A POST, as the engine's runs are, so it carries the session's token; it changes nothing.
          const input = { topic, when: at }
          return await write('obs.replay', input, (o) => client.obs.replay(input, o))
        } catch (error) {
          // Nothing was published before what agents get now: there is no before to compare with.
          if (at === 'before' && toApiError(error).status === 412) return null
          throw error
        }
      }
      const [now, before] = await Promise.all([run('now'), run('before')])
      const shown = when === 'before' ? (before ?? now!) : now!
      return replayOf(shown, named, when === 'before' ? now : before, now!.answer.edition)
    },
    getSavedViews: async () => (await read(() => client.obs.views.list())).map(savedViewOf),
    saveView: async ({ name, filters }) => {
      const input = { name, filters }
      const saved = await write('obs.views.save', input, (o) => client.obs.views.save(input, o))
      return { id: saved.id }
    },
    removeView: async ({ id }) => {
      await write('obs.views.remove', { id }, (o) => client.obs.views.remove({ id }, o))
    },
    // Saved questions and the free check (FR-526): someone who manages no domain has none.
    getSavedQuestions: async () => {
      const now = new Date()
      return (await read(() => client.savedQuestions.list({}))).map((q) => savedQuestionOf(q, now))
    },
    getSavedCheck: async () =>
      savedCheckOf(await read(() => client.savedQuestions.status({})), new Date()),
    checkSavedQuestions: async ({ domain }) => {
      const input = domain ? { areaId: domain } : {}
      const done = await write('savedQuestions.check', input, (o) =>
        client.savedQuestions.check(input, o),
      )
      return { checked: done.run.checked }
    },
    saveQuestion: async ({ question, from, origin }) => {
      const input = {
        areaId: question.domain,
        question: question.question,
        origin: origin ?? 'ask',
        ...(from ? { expectItems: from.filter(isItemId) } : {}),
      }
      const saved = await write('savedQuestions.create', input, (o) =>
        client.savedQuestions.create(input, o),
      )
      return { id: saved.question.id, undo: saved.undo }
    },
    removeSavedQuestion: async ({ id }) => {
      await write('savedQuestions.remove', { id }, (o) => client.savedQuestions.remove({ id }, o))
    },
    keepNewAnswer: async ({ id }) => {
      const kept = await write('savedQuestions.keep', { id }, (o) =>
        client.savedQuestions.keep({ id }, o),
      )
      return { undo: kept.undo }
    },
    // Alerts (FR-621): rules that raise Inbox cards, as the person may read and change them.
    getAlerts: async () => {
      const [rules, raised] = await Promise.all([
        read(() => client.alerts.rules()),
        read(() => client.alerts.raised({})),
      ])
      return alertsOf(rules, raised, new Date())
    },
    setAlertRule: async ({ id, on }) => {
      const input = { rule: id, enabled: on }
      await write('alerts.setRule', input, (o) => client.alerts.setRule(input, o))
    },
    setAlertThreshold: async ({ id, value }) => {
      const threshold = thresholdOfWords(id, value)
      if (threshold === null)
        throw new ApiError('invalid', "This rule's sentence doesn't offer that threshold.")
      const input = { rule: id, threshold }
      await write('alerts.setRule', input, (o) => client.alerts.setRule(input, o))
    },
    muteAlert: async ({ id, domains, muted }) => {
      const input = { rule: id, areaIds: domains, muted }
      await write('alerts.mute', input, (o) => client.alerts.mute(input, o))
    },
  }

  return Object.fromEntries(
    heedApiMethods.map((method) => [
      method,
      (wired as Partial<Record<HeedApiMethod, unknown>>)[method] ?? notAvailable(method),
    ]),
  ) as unknown as HeedApi
}
